// Initialize aggregation
const today = new Date();
const weekAgo = new Date(today.getTime() - 7 * 24 * 60 * 60 * 1000);

return {
  aggregationId: `agg_${Date.now()}`,
  startDate: weekAgo.toISOString(),
  endDate: today.toISOString(),
  sources: [
    { name: 'CVE Database', url: 'https://cve.mitre.org/data/downloads/allitems-cvrf-year-2024.xml' },
    { name: 'Cybersecurity News', url: 'https://feeds.feedburner.com/TheHackersNews' },
    { name: 'Bug Bounty Programs', url: 'https://www.bugcrowd.com/bug-bounty-list/' },
    { name: 'Security Advisories', url: 'https://github.com/advisories' },
    { name: 'NIST NVD', url: 'https://nvd.nist.gov/vuln/data-feeds' }
  ]
};

// Parse different feed formats (RSS, JSON, XML, HTML)
const data = $input.first().json.data || '';
const sourceName = $input.first().json.source.name;
const sourceUrl = $input.first().json.source.url;

let items = [];

// Detect format and parse accordingly
if (data.includes('<?xml') || data.includes('<rss')) {
  // RSS/XML Feed
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  const titleRegex = /<title><!\[CDATA\[([^\]]+)\]\]><\/title>|<title>([^<]+)<\/title>/i;
  const linkRegex = /<link>([^<]+)<\/link>/i;
  const descRegex = /<description><!\[CDATA\[([^\]]+)\]\]><\/description>|<description>([^<]+)<\/description>/i;
  const dateRegex = /<pubDate>([^<]+)<\/pubDate>/i;

  let match;
  while ((match = itemRegex.exec(data)) !== null) {
    const itemXml = match[1];
    const titleMatch = titleRegex.exec(itemXml);
    const linkMatch = linkRegex.exec(itemXml);
    const descMatch = descRegex.exec(itemXml);
    const dateMatch = dateRegex.exec(itemXml);

    if (titleMatch && linkMatch) {
      items.push({
        title: (titleMatch[1] || titleMatch[2] || '').trim(),
        url: linkMatch[1].trim(),
        description: (descMatch ? (descMatch[1] || descMatch[2] || '') : '').substring(0, 500),
        publishDate: dateMatch ? dateMatch[1] : null,
        source: sourceName
      });
    }
  }
} else if (data.startsWith('{') || data.startsWith('[')) {
  // JSON format
  try {
    const jsonData = JSON.parse(data);
    const itemsArray = Array.isArray(jsonData) ? jsonData : (jsonData.items || jsonData.data || []);

    items = itemsArray.slice(0, 50).map(item => ({
      title: item.title || item.name || item.summary || 'No title',
      url: item.url || item.link || item.html_url || '',
      description: (item.description || item.summary || '').substring(0, 500),
      publishDate: item.published_at || item.created_at || item.date || null,
      source: sourceName
    }));
  } catch (e) {
    items = [{ error: 'Failed to parse JSON', source: sourceName }];
  }
} else {
  // HTML scraping fallback
  const h2Regex = /<h[2-3][^>]*>([^<]+)<\/h[2-3]>/gi;
  const matches = [...data.matchAll(h2Regex)];

  items = matches.slice(0, 20).map((m, idx) => ({
    title: m[1].trim(),
    url: sourceUrl + '#item-' + idx,
    description: 'Extracted from HTML',
    publishDate: new Date().toISOString(),
    source: sourceName
  }));
}

return {
  aggregationId: $json.aggregationId,
  source: sourceName,
  sourceUrl: sourceUrl,
  itemsFound: items.length,
  items: items,
  fetchedAt: new Date().toISOString()
};

// Extract and categorize security topics
const items = $json.items || [];

const categorizedItems = items.map(item => {
  const text = (item.title + ' ' + item.description).toLowerCase();

  // Category detection
  let category = 'general';
  let severity = 'info';
  let tags = [];

  if (text.includes('cve-') || text.includes('vulnerability')) {
    category = 'vulnerability';
    tags.push('CVE');
  }
  if (text.includes('bug bounty') || text.includes('bounty')) {
    category = 'bug-bounty';
    tags.push('bug-bounty');
  }
  if (text.includes('exploit') || text.includes('zero-day') || text.includes('0day')) {
    category = 'exploit';
    severity = 'critical';
    tags.push('exploit');
  }
  if (text.includes('patch') || text.includes('update') || text.includes('fix')) {
    category = 'patch';
    tags.push('patch');
  }
  if (text.includes('malware') || text.includes('ransomware')) {
    category = 'malware';
    severity = 'high';
    tags.push('malware');
  }
  if (text.includes('critical') || text.includes('severe')) {
    severity = 'critical';
  } else if (text.includes('high')) {
    severity = 'high';
  } else if (text.includes('medium') || text.includes('moderate')) {
    severity = 'medium';
  }

  return {
    ...item,
    category: category,
    severity: severity,
    tags: tags,
    aggregationId: $json.aggregationId
  };
});

return categorizedItems;

// Generate weekly summary report
const allItems = $input.all();

const stats = {
  totalItems: allItems.length,
  byCategory: {},
  bySeverity: {},
  bySource: {},
  criticalAlerts: []
};

allItems.forEach(item => {
  const data = item.json;

  // Count by category
  stats.byCategory[data.category] = (stats.byCategory[data.category] || 0) + 1;

  // Count by severity
  stats.bySeverity[data.severity] = (stats.bySeverity[data.severity] || 0) + 1;

  // Count by source
  stats.bySource[data.source] = (stats.bySource[data.source] || 0) + 1;

  // Collect critical alerts
  if (data.severity === 'critical') {
    stats.criticalAlerts.push({
      title: data.title,
      url: data.url,
      source: data.source
    });
  }
});

return {
  aggregationId: $input.first().json.aggregationId,
  weekEnding: new Date().toISOString().split('T')[0],
  statistics: stats,
  generatedAt: new Date().toISOString()
};

